import{_ as n,a0 as o,w as p,s as l,ao as u,I as s,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop","title":"Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死","tag":"201509","desc":""},"relativePath":"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop.md","filePath":"[post].md"}'),d={name:"201509/20150817 Linux FAQs with Answers--How to fix Wireshark GUI freeze on Linux desktop.md"};function k(h,e,L,x,_,f){const r=o("Link");return p(),l("div",null,[e[13]||(e[13]=u(`<h1 id="linux-有問必答-如何解決-linux-上的-wireshark-界面僵死" tabindex="-1">Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死 <a class="header-anchor" href="#linux-有問必答-如何解決-linux-上的-wireshark-界面僵死" aria-label="Permalink to “Linux 有問必答：如何解決 Linux 上的 Wireshark 界面僵死”">​</a></h1><blockquote><p><strong>問題</strong>: 當我試圖在 Ubuntu 上的 Wireshark 中打開一個 pre-recorded 數據包轉儲時，它的界面突然死機，在我運行 Wireshark 的終端出現了下面的錯誤和警告。我該如何解決這個問題？</p></blockquote><pre><code>(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GObject&#39;
(wireshark:3480): GLib-GObject-CRITICAL **: g_object_set_qdata_full: assertion &#39;G_IS_OBJECT (object)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkRange&#39;
(wireshark:3480): Gtk-CRITICAL **: gtk_range_get_adjustment: assertion &#39;GTK_IS_RANGE (range)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkOrientable&#39;
(wireshark:3480): Gtk-CRITICAL **: gtk_orientable_get_orientation: assertion &#39;GTK_IS_ORIENTABLE (orientable)&#39; failed
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkScrollbar&#39;
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GtkWidget&#39;
(wireshark:3480): GLib-GObject-WARNING **: invalid unclassed pointer in cast to &#39;GObject&#39;
(wireshark:3480): GLib-GObject-CRITICAL **: g_object_get_qdata: assertion &#39;G_IS_OBJECT (object)&#39; failed
(wireshark:3480): Gtk-CRITICAL **: gtk_widget_set_name: assertion &#39;GTK_IS_WIDGET (widget)&#39; failed
</code></pre><p>Wireshark 是一個基於 GUI 的數據包捕獲和嗅探工具。該工具被網絡管理員普遍使用，網絡安全工程師或開發人員對於各種任務的數據包級的網絡分析是必需的，例如在網絡故障，漏洞測試，應用程序調試，或逆向協議工程是必需的。 Wireshark 允許實時記錄數據包，並通過便捷的圖形用户界面瀏覽他們的協議首部和有效負荷。</p><p><img src="https://farm1.staticflickr.com/722/20584224675_f4d7a59474_c.jpg" alt=""></p><p>這是 Wireshark 的 UI，尤其是在 Ubuntu 桌面下運行時，當你向上或向下滾動分組列表視圖時，或開始加載一個 pre-recorded 包轉儲文件時，有時會掛起或凍結，並出現以下錯誤。</p><p><img src="https://farm1.staticflickr.com/589/20062177334_47c0f2aeae_c.jpg" alt=""></p><p>顯然，這個錯誤是由 Wireshark 和疊加滾動條之間的一些不兼容造成的，在最新的 Ubuntu 桌面還沒有被解決（例如，Ubuntu 15.04 的桌面）。</p><p>一種避免 Wireshark 的 UI 卡死的辦法就是 <strong>暫時禁用疊加滾動條</strong>。在 Wireshark 上有兩種方法來禁用疊加滾動條，這取決於你在桌面上如何啓動 Wireshark 的。</p><h3 id="命令列解決方法" tabindex="-1">命令列解決方法 <a class="header-anchor" href="#命令列解決方法" aria-label="Permalink to “命令列解決方法”">​</a></h3><p>疊加滾動條可以通過設置&quot;<strong>LIBOVERLAY_SCROLLBAR</strong>&quot;環境變量為“0”來被禁止。</p><p>所以，如果你是在終端使用命令列啓動 Wireshark 的，你可以在 Wireshark 中禁用疊加滾動條，如下所示。</p><p>打開你的 .bashrc 文件，並定義以下 alias。</p><pre><code>alias wireshark=&quot;LIBOVERLAY_SCROLLBAR=0 /usr/bin/wireshark&quot;
</code></pre><h3 id="桌面啓動解決方法" tabindex="-1">桌面啓動解決方法 <a class="header-anchor" href="#桌面啓動解決方法" aria-label="Permalink to “桌面啓動解決方法”">​</a></h3><p>如果你是使用桌面啓動器啓動的 Wireshark，你可以編輯它的桌面啓動器文件。</p><pre><code>$ sudo vi /usr/share/applications/wireshark.desktop
</code></pre><p>查找以&quot;Exec&quot;開頭的行，並如下更改。</p><pre><code>Exec=env LIBOVERLAY_SCROLLBAR=0 wireshark %f
</code></pre><p>雖然這種解決方法可以在系統級幫助到所有桌面用户，但升級 Wireshark 就沒用了。如果你想保留修改的 .desktop 文件，如下所示將它複製到你的主目錄。</p><pre><code>$ cp /usr/share/applications/wireshark.desktop ~/.local/share/applications/ 
</code></pre><hr>`,22)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),i(r,{href:"http://ask.xmodulo.com/fix-wireshark-gui-freeze-linux-desktop.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/fix-wireshark-gui-freeze-linux-desktop.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),i(r,{href:"http://ask.xmodulo.com/author/nanni"},{default:a(()=>[...e[2]||(e[2]=[t("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),i(r,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[3]||(e[3]=[t("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),i(r,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const g=n(d,[["render",k]]);export{G as __pageData,g as default};
